lock_statements_source:
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    least(a::text,b::text) || ':' || greatest(a::text,b::text), 0));

-- SHARE blocks status/deletion changes but is compatible with the existing
  -- report intake actor SHARE after its Hangout parent lock.
  perform 1 from public.accounts where id=actor for share;

every absent row denies now.
 if p_operation='send_hangout_message' then
  perform 1 from private.pilot_capabilities where key='hangout_chat' for share;

else
    select p.state into participant_state from public.hangout_participants p
     where p.hangout_id=source_id and p.account_id=subject for share;

if p_operation='create_hangout' then
  if p_request_id is not null then
   perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor_id::text||p_request_id::text,0));

begin
  select enabled into gate_enabled from private.large_hangout_feature_gate
    where singleton for share;

-- Serialize retries of one creation key before locking the unordered pair.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'friendship-request:' || actor::text || ':' || p_request_id::text, 0));

if p_action='reply' and p_reply_request_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'dm-request:'||actor::text||':'||p_reply_request_id::text,0));

if r.target_type='user' then
    select m.university_id into subject_campus from public.university_memberships m
      where m.user_id=r.target_id for share;

triggers.definition_source:
create trigger account_sanctions_immutable before update or delete
  on private.account_sanctions for each row
  execute function private.reject_moderation_evidence_change();

create trigger pals_active_dm_pair_write before update or delete
  on private.dm_pairs for each row
  execute function private.require_active_student_source_write();

create trigger pals_active_friendship_write before update or delete
  on private.friendships for each row
  execute function private.require_active_student_source_write();

create trigger large_hangout_signal_immutable before update or delete
  on private.large_hangout_signals for each row
  execute function private.reject_large_hangout_signal_change();

create trigger moderation_audit_immutable before update or delete
  on private.moderation_audit for each row
  execute function private.reject_moderation_evidence_change();

create trigger moderation_case_reopen_sanction before update of disposition
  on private.moderation_cases for each row
  execute function private.clear_reopened_case_sanction();

create trigger pals_active_notification_read_write before update of read_at
  on private.notification_items for each row
  execute function private.require_active_student_source_write();

create trigger pals_active_notification_preference_write before insert or update
  on private.notification_preferences for each row
  execute function private.require_active_student_source_write();
